local EvaporatingBasinMaker = {}
local PRODUCTS = {
    simple_clay_evaporating = { name = "Preprosta glinena uparjevalna kad", clayCost = 3, copperCost = 1, time = 4, cost = 80, science = 20, happiness = 1, description = "Preprosta glinena uparjevalna kad za uparjanje." },
    copper_basin_evaporating = { name = "Bakrena uparjevalna kad", clayCost = 2, copperCost = 2, time = 6, cost = 200, science = 35, happiness = 2, prestige = 2, description = "Bakrena uparjevalna kad za trgovce." },
    silver_rim_evaporating = { name = "Srebrnorobna uparjevalna kad", clayCost = 2, silverCost = 1, copperCost = 2, time = 10, cost = 480, science = 50, happiness = 2, prestige = 6, description = "Srebrnorobna uparjevalna kad za plemiče." },
    gold_trimmed_evaporating = { name = "Zlatookrasna uparjevalna kad", clayCost = 2, goldCost = 1, silverCost = 1, copperCost = 2, time = 14, cost = 1200, science = 65, happiness = 3, prestige = 14, description = "Zlatookrasna uparjevalna kad za visoke plemiče." },
    jewel_set_evaporating = { name = "Draguljasta uparjevalna kad", clayCost = 2, goldCost = 1, silverCost = 1, copperCost = 2, jewelCost = 1, time = 18, cost = 2600, science = 80, happiness = 5, prestige = 27, description = "Uparjevalna kad z draguljem za visoko plemstvo." },
    royal_grand_evaporating = { name = "Kraljevski veliki uparjevalna kad", clayCost = 3, goldCost = 2, silverCost = 2, copperCost = 2, jewelCost = 2, pearlCost = 2, time = 25, cost = 5600, science = 95, happiness = 12, prestige = 58, description = "Velika kraljevska uparjevalna kad z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    evaporating_workshop = { name = "Uparjevalna delavnica", cost = { gold = 270, wood = 120, stone = 140, clay = 8, copper = 6 }, upkeep = 6, qualityBonus = 5 },
    alchemy_loft = { name = "Alkemična podstrešje", cost = { gold = 980, wood = 280, stone = 280, silver = 6, copper = 8 }, upkeep = 22, qualityBonus = 18 },
    master_evaporating_atelier = { name = "Mojstrski uparjevalni atelje", cost = { gold = 2650, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 61, qualityBonus = 30 },
    royal_alchemy_palace = { name = "Kraljevska alkemična palača", cost = { gold = 11300, wood = 580, stone = 760, gold = 72, jewel = 18 }, upkeep = 225, qualityBonus = 55, prestigeBonus = 50 },
}
EvaporatingBasinMaker.clayStock = 14; EvaporatingBasinMaker.copperStock = 14; EvaporatingBasinMaker.silverStock = 6; EvaporatingBasinMaker.goldStock = 6; EvaporatingBasinMaker.jewelStock = 4; EvaporatingBasinMaker.pearlStock = 4
EvaporatingBasinMaker.productStock = {}; EvaporatingBasinMaker.buildings = {}; EvaporatingBasinMaker.maker = nil; EvaporatingBasinMaker.activeMaking = {}; EvaporatingBasinMaker.totalProducts = 0; EvaporatingBasinMaker.dayTimer = 0
function EvaporatingBasinMaker.init() EvaporatingBasinMaker.clayStock=14; EvaporatingBasinMaker.copperStock=14; EvaporatingBasinMaker.silverStock=6; EvaporatingBasinMaker.goldStock=6; EvaporatingBasinMaker.jewelStock=4; EvaporatingBasinMaker.pearlStock=4; EvaporatingBasinMaker.productStock={}; EvaporatingBasinMaker.buildings={}; EvaporatingBasinMaker.maker=nil; EvaporatingBasinMaker.activeMaking={}; EvaporatingBasinMaker.totalProducts=0; EvaporatingBasinMaker.dayTimer=0; print("[EvaporatingBasinMaker] Royal Evaporating Basin Maker System initialized (6 products, 4 buildings)") end
function EvaporatingBasinMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; EvaporatingBasinMaker.maker={name=n or ("Uparjevalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Uparjevalec najet: %s (spretnost: %d)",EvaporatingBasinMaker.maker.name,s),"success") end; return true end
function EvaporatingBasinMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function EvaporatingBasinMaker.build(id) local ok,e=EvaporatingBasinMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(EvaporatingBasinMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function EvaporatingBasinMaker.getQualityBonus() local b=0; for _,bd in ipairs(EvaporatingBasinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function EvaporatingBasinMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.clayCost and EvaporatingBasinMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.copperCost and EvaporatingBasinMaker.copperStock<(d.copperCost or 0) then return false,"Premalo bakra" end; if d.silverCost and EvaporatingBasinMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and EvaporatingBasinMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and EvaporatingBasinMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and EvaporatingBasinMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #EvaporatingBasinMaker.buildings==0 then return false,"Potrebna uparjevalna delavnica" end; if not EvaporatingBasinMaker.maker then return false,"Potreben uparjevalec" end; return true end
function EvaporatingBasinMaker.make(pt,qty) qty=qty or 1; local ok,e=EvaporatingBasinMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.clayCost then EvaporatingBasinMaker.clayStock=EvaporatingBasinMaker.clayStock-d.clayCost*qty end; if d.copperCost then EvaporatingBasinMaker.copperStock=EvaporatingBasinMaker.copperStock-d.copperCost*qty end; if d.silverCost then EvaporatingBasinMaker.silverStock=EvaporatingBasinMaker.silverStock-d.silverCost*qty end; if d.goldCost then EvaporatingBasinMaker.goldStock=EvaporatingBasinMaker.goldStock-d.goldCost*qty end; if d.jewelCost then EvaporatingBasinMaker.jewelStock=EvaporatingBasinMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then EvaporatingBasinMaker.pearlStock=EvaporatingBasinMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if EvaporatingBasinMaker.maker then t=math.max(1,t-math.floor(EvaporatingBasinMaker.maker.skill/13)) end; table.insert(EvaporatingBasinMaker.activeMaking,{id="evaporatingbasin_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function EvaporatingBasinMaker.completeMaking(m) local q=1.0+(EvaporatingBasinMaker.getQualityBonus()/100); if EvaporatingBasinMaker.maker then q=q+(EvaporatingBasinMaker.maker.skill/140) end; q=math.min(2.5,q); EvaporatingBasinMaker.productStock[m.productType]=(EvaporatingBasinMaker.productStock[m.productType] or 0)+m.quantity; EvaporatingBasinMaker.totalProducts=EvaporatingBasinMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if EvaporatingBasinMaker.maker then EvaporatingBasinMaker.maker.itemsMade=EvaporatingBasinMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then EvaporatingBasinMaker.maker.skill=math.min(100,EvaporatingBasinMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Uparjevalna kad izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"evaporatingbasin.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function EvaporatingBasinMaker.update(dt) if not _G.state then return end; EvaporatingBasinMaker.dayTimer=EvaporatingBasinMaker.dayTimer+dt; if EvaporatingBasinMaker.dayTimer>=30 then EvaporatingBasinMaker.dayTimer=0; for i=#EvaporatingBasinMaker.activeMaking,1,-1 do local m=EvaporatingBasinMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then EvaporatingBasinMaker.completeMaking(m); table.remove(EvaporatingBasinMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(EvaporatingBasinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if EvaporatingBasinMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function EvaporatingBasinMaker.getStats() return {clayStock=EvaporatingBasinMaker.clayStock,copperStock=EvaporatingBasinMaker.copperStock,silverStock=EvaporatingBasinMaker.silverStock,goldStock=EvaporatingBasinMaker.goldStock,jewelStock=EvaporatingBasinMaker.jewelStock,pearlStock=EvaporatingBasinMaker.pearlStock,productStock=EvaporatingBasinMaker.productStock,numBuildings=#EvaporatingBasinMaker.buildings,hasMaker=EvaporatingBasinMaker.maker~=nil,makerName=EvaporatingBasinMaker.maker and EvaporatingBasinMaker.maker.name or "—",makerSkill=EvaporatingBasinMaker.maker and EvaporatingBasinMaker.maker.skill or 0,activeMaking=#EvaporatingBasinMaker.activeMaking,totalProducts=EvaporatingBasinMaker.totalProducts} end
return EvaporatingBasinMaker
